      ],
      "recommended_action": "Investigate CI claims reporting, underwriting mix, and expected rate calibration for structural scatter; apply lower credibility weighting to CI experience in pricing/valuation; monitor for data quality issues or un-modeled risk factors"
    }
  ]
}

